sys_transform_script.script:
//The onBefore event script is processed at the start of a row transformation, before the source row is transformed into the target row.
//https://docs.servicenow.com/bundle/xanadu-integrate-applications/page/script/server-scripting/reference/r_MapWithTransformationEventScripts.html
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    const actionTaken = source.u_action_s__taken_by_manager.toString().trim(); //some entries are " ", we need to remove them
	const timeStamp = new Date().toISOString(); //performance.timeOrigin + performance.now();
    const infoStr = 'OHS - ' + timeStamp + ' - Row: ' + source.sys_import_row +
        ' - onBefore - ';

    //only return if there's an action
    if (actionTaken === null || actionTaken === '' || actionTaken === '0') {
        ignore = true;
    } else {
        log.info(infoStr + 'we push the action (we don\'t ignore), action taken: ' + actionTaken);
    }

})(source, map, log, target);
